var ACT=['抵达与安顿','老城漫游','博物馆 / 展览','自然与户外','在地美食探索','自由活动',
         '周边短途','夜游漫步','手信与购物','温泉与放松'];
var PACK=['证件 / 护照','充电宝与充电器','常备药品','换洗衣物','舒适步行鞋','雨具','现金与银行卡','行程单备份'];
function slotsForPace(pace){
  if(pace==='relaxed') return ['10:30','15:30'];
  if(pace==='packed') return ['09:00','11:00','14:00','17:00','19:30'];
  return ['09:30','13:00','16:30'];
}
function buildItinerary(dest, days, pace){
  days=Math.round(+days);
  if(isNaN(days)||days<1) return {error:'天数须为正整数'};
  if(days>30) days=30;
  var times=slotsForPace(pace); var out=[]; var k=0;
  for(var d=1; d<=days; d++){
    var slots=[];
    for(var i=0;i<times.length;i++){ slots.push({time:times[i], activity:ACT[k%ACT.length]}); k++; }
    out.push({day:d, slots:slots});
  }
  return {dest:String(dest||'目的地'), days:days, pace:pace, daysOut:out, packing:PACK};
}
var EXPORTS={buildItinerary:buildItinerary, slotsForPace:slotsForPace, ACT:ACT, PACK:PACK};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ItineraryForgePure = EXPORTS; }
